let results=[],ranPeriod='',ranIncludesPending=false,ranDataAt='',ranKeyword='',controller=null,detailIndex=null,chargeRun=0,chargeHideTimer=null;
function setCharge(value,text){const n=Math.max(0,Math.min(100,value));$('progressFill').style.width=n+'%';$('progress').setAttribute('aria-valuenow',String(Math.round(n)));$('progress').setAttribute('aria-busy',n<100?'true':'false');$('progressStage').textContent=text;$('progressState').textContent=n===100?'완료':'조회 중';}
