function assertActive(signal){if(signal?.aborted)throw new DOMException('조회 취소','AbortError');}
async function request(url,body,signal){assertActive(signal);const resp=await fetch(url,{credentials:'same-origin',signal,method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','Accept':'application/json'}:{'Accept':'application/json'},body:body?JSON.stringify(body):undefined});if(!resp.ok)throw Error('위킵 조회 실패 ('+resp.status+')');const json=await resp.json().catch(()=>{throw Error('위킵 로그인 세션이 만료되었습니다. 원래 화면에서 다시 로그인해 주세요.')});assertActive(signal);if(!json.result)throw Error(json.message||'위킵 조회 오류');return json.data;}
async function pool(items,fn,workers=3){let next=0;await Promise.all(Array.from({length:Math.min(workers,items.length)},async()=>{while(next<items.length){const i=next++;await fn(items[i],i);}}));}
