const fallbackCache=new Map(),orderProofCache=new Map();
async function orderRows(params,signal){assertActive(signal);const resp=await fetch('/fbw/admin/v2/order/searchOrder?'+params,{credentials:'same-origin',signal});if(!resp.ok)throw Error('판매처 조회 실패');const doc=new DOMParser().parseFromString(await resp.text(),'text/html');assertActive(signal);if(doc.title.includes('로그인'))throw Error('위킵 로그인 세션이 만료되었습니다.');return [...doc.querySelectorAll('#orderItemList tr[orderNo]')].map(tr=>({orderNo:tr.getAttribute('orderNo'),cells:[...tr.querySelectorAll('td')].map(td=>td.textContent.trim())}));}
async function fallbackOrders(from,end,signal){const key=from+'|'+end;if(!fallbackCache.has(key)){const work=(async()=>{const lookback=new Date(from+'T12:00:00Z');lookback.setUTCDate(lookback.getUTCDate()-90);const all=[];for(const saleChannelNo of ['SCNA86CD363DAU6OO','SCNE41DE36D670XPI']){for(let page=1;page<=200;page++){const p=new URLSearchParams({page:String(page),searchLength:'100',orderStatus:'',startDate:dateStr(lookback).replaceAll('-',''),endDate:end.replaceAll('-',''),saleChannelNo});const rows=await orderRows(p,signal);all.push(...rows);if(rows.length<100)break;if(page===200)throw Error('밀크런 보조 조회 범위가 너무 큽니다. 기간을 줄여 주세요.');}}return [...new Map(all.map(r=>[r.orderNo,r])).values()];})();fallbackCache.set(key,work);work.catch(()=>fallbackCache.delete(key));}return await fallbackCache.get(key);}
