function shipmentSplit(row){let parcel=0,milk=0;for(const [name,qty] of Object.entries(row.channels)){const n=name.replace(/[\s_-]/g,'');if(n==='밀크런')milk+=qty;else if(n==='로켓택배')parcel+=qty;}return {parcel,milk};}
