 function rowHTML(e,rank,denom){const [from,to]=periodDates(),days=(Date.parse(to)-Date.parse(from))/86400000+1,avg=e.r.shipped/Math.max(1,days),coverage=avg>0?e.r.available/avg:null,check=e.pendingIssue?'<span class="md-badge bad">배정 확인 필요</span>':e.r.available===0?'<span class="md-badge bad">가용재고 없음</span>':coverage!==null&&coverage<3?'<span class="md-badge warn">3일분 미만</span>':'<span class="md-badge">재고 참고</span>',delta=e.delta===0?'동일':(e.delta>0?'+':'')+fmt(e.delta)+'개',deltaSub=e.previous===0?(e.currentActual>0?'전일 0개 → 출고 발생':'전일 0개'):'전일 '+fmt(e.previous)+'개 · '+(e.delta>0?'+':'')+(e.delta/e.previous*100).toFixed(1)+'%';return '<tr data-md-index="'+e.i+'" data-md-day="'+(e.day||'')+'"><td>'+rank+'</td><td class="name">'+esc(e.r.name)+(e.r.variation&&e.r.variation!=='-'?'<span class="sub">'+esc(e.r.variation)+'</span>':'')+'<span class="sub">비중 '+(denom?e.total/denom*100:0).toFixed(1)+'% · 상세 보기</span></td><td class="rank-qty">'+(e.pendingIssue?'확인 필요':fmt(e.total))+'</td><td>'+fmt(e.actual)+'</td><td>'+(e.withPending?displayPending(e):'당시 자료 없음')+'</td><td class="'+(e.delta>0?'up':e.delta<0?'down':'')+'">'+delta+'<span class="sub">'+deltaSub+(e.day===null?'<br>종료일 실제 출고 기준':'')+'</span></td><td>'+esc(e.top)+'<span class="sub">'+fmt(e.topQty)+'개 · 로켓 '+fmt(e.rocket)+'개'+(e.unknown?' · 미확인 '+fmt(e.unknown)+'개':'')+'</span></td><td>'+fmt(e.r.available)+'<span class="sub">'+(coverage===null?'평균 출고 없음':coverage.toFixed(1)+'일분 참고')+'</span></td><td>'+check+'</td></tr>';}
