 function showDaily(){if(!ranDataAt||!results.length)return;const ranked=rangeEntries(),known=ranked.reduce((n,e)=>n+e.total,0),actual=results.reduce((n,r)=>n+r.shipped,0),pending=ranked.reduce((n,e)=>n+(e.withPending&&!e.pendingIssue?e.pending||0:0),0),issue=ranIncludesPending&&results.some(r=>r.pendingIssue);$('mdTotal').textContent=issue?'확인 필요':fmt(known)+'개';$('mdTotalSub').textContent='실제 '+fmt(actual)+'개'+(ranIncludesPending?' · 현재 배정 '+(issue?'확인 필요':fmt(pending)+'개'):' · 과거 배정 미포함');$('mdProducts').textContent=fmt(ranked.length)+'개';$('mdTopName').textContent=ranked[0]?.r.name||'출고 없음';$('mdTopQty').textContent=ranked.length?fmt(ranked[0].total)+'개 · 확인된 수량 순':'선택 기간의 출고 품목 없음';$('mdTopShare').textContent=known?(ranked.slice(0,3).reduce((n,e)=>n+e.total,0)/known*100).toFixed(1)+'%':'-';$('basisNotice').textContent='순위 = 해당 일자 실제 출고 + 오늘의 확인된 배정 대기. 과거 배정은 넣지 않습니다. 전일 대비는 실제 출고만 비교합니다.';$('dailyLists').className='';let html=issue?'<div class="md-warning">배정 검증이 필요한 상품이 있어 순위는 확인된 수량 기준의 잠정 순위입니다. 미확정 배정을 0으로 확정하지 않았습니다.</div>':'';if(dailyView==='period'){html+='<section class="daily-day"><div class="day-title"><h2>선택 기간 합산 순위</h2><span>'+esc(periodDates().join(' ~ '))+' · '+ranked.length+'개 출고 품목</span></div>'+(ranked.length?tableHTML(ranked):'<div class="daily-empty">출고·배정이 있는 품목이 없습니다.</div>')+'</section>';}else for(const day of daysInPeriod()){const list=sortEntries(results.map((r,i)=>entry(r,i,day))),n=list.reduce((n,e)=>n+e.total,0);html+='<section class="daily-day"><div class="day-title"><h2>'+day+(day===today()?' · 오늘':'')+'</h2><span>'+fmt(n)+'개 확인 · '+list.length+'개 품목 · '+(day===periodDates()[1]&&ranIncludesPending?'조회 시점 배정 포함':'실제 출고만')+'</span></div>'+(list.length?tableHTML(list):'<div class="daily-empty">이 날 확인된 출고 품목이 없습니다.</div>')+'</section>';}$('dailyLists').innerHTML=html;root.querySelectorAll('[data-md-index]').forEach(tr=>tr.onclick=()=>openDetail(Number(tr.dataset.mdIndex),tr.dataset.mdDay||null));}
 function openDetail(index,day){detailIndex=index;dailyDetailDay=day;const e=entry(results[index],index,day);$('details').hidden=false;$('detailXlsx').disabled=false;$('detailTitle').textContent=e.r.name+' · '+(day||'선택 기간 합산')+' 판매처 상세';const names=Object.entries(e.channels).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'ko'));$('detailRows').innerHTML='<p style="font-size:14px;margin-bottom:12px">'+(e.withPending?'오늘의 확인된 배정 대기를 포함합니다.':'실제 출고만 표시합니다. 당시 배정 자료는 없습니다.')+'</p><table><thead><tr><th>판매처</th><th>구분</th><th>합계</th><th>실제 출고</th><th>배정 대기</th></tr></thead><tbody>'+names.map(([name,qty])=>{const ac=day?e.r.shippedDaily[day]?.[name]||0:e.r.shippedChannels[name]||0;return '<tr><td>'+esc(name)+'</td><td>'+esc(name==='판매처 미확인'?'확인 필요':rocketChannel(name)?'로켓배송':'로켓배송 외')+'</td><td>'+(e.pendingIssue?'확인 필요':fmt(qty))+'</td><td>'+fmt(ac)+'</td><td>'+(e.withPending?(e.pendingIssue?'확인 필요':fmt(e.r.pendingChannels[name]||0)):'당시 자료 없음')+'</td></tr>';}).join('')+'</tbody></table>';}
 const baseRender=render;render=function(){const answer=baseRender();showDaily();return answer;};
 $('byDays').onclick=()=>{dailyView='days';$('byDays').setAttribute('aria-pressed','true');$('byPeriod').setAttribute('aria-pressed','false');showDaily();};$('byPeriod').onclick=()=>{dailyView='period';$('byDays').setAttribute('aria-pressed','false');$('byPeriod').setAttribute('aria-pressed','true');showDaily();};$('dailyLimit').onchange=()=>{dailyLimit=Number($('dailyLimit').value);showDaily();};
 const baseSubmit=$('form').onsubmit;$('form').onsubmit=async e=>{if(controller){e.preventDefault();return;}if(!controller){for(const id of ['mdTotal','mdProducts','mdTopName','mdTopQty','mdTopShare'])$(id).textContent='-';$('mdTotalSub').textContent='조회 중';$('dailyLists').innerHTML='<div class="daily-empty">품목별 출고와 판매처를 확인하고 있습니다.</div>';}await baseSubmit(e);if(!ranDataAt){$('mdTotalSub').textContent=$('status').textContent.includes('중지')?'조회 중지':'조회 미완료';$('dailyLists').innerHTML='<div class="daily-empty">'+esc($('status').textContent)+'</div>';}else if(results.length){showDaily();}else if(!results.length){$('dailyLists').innerHTML='<div class="daily-empty">일치하는 상품이 없습니다.</div>';$('mdProducts').textContent='0개';$('mdTotal').textContent='0개';$('mdTotalSub').textContent='조회 완료 · 일치하는 상품 없음';$('mdTopName').textContent='해당 상품 없음';$('mdTopQty').textContent='검색어와 기간을 확인해 주세요.';}};
 function dailyWorkbook(mode){if(controller||!ranDataAt||!results.length)throw Error('완료된 검색 결과가 필요합니다.');const detail=mode==='detail',ranked=rangeEntries(),headers=['일자/기간','순위','상품명','옵션명','SKU','출고+배정 (개)','실제 출고 (개)','배정 대기 (개)','전일 실제 출고 (개)','전일 대비 실제 출고 (개)','주 판매처','현재 가용재고 (개)','배정 검증'],toRow=(e,rank)=>[e.day||periodDates().join(' ~ '),rank,e.r.name,e.r.variation==='-'?'':e.r.variation||'',String(e.r.sku),e.pendingIssue?'확인 필요':e.total,e.actual,e.withPending?(e.pendingIssue?'확인 필요':e.pending):'당시 자료 없음',e.previous,e.delta,e.top,e.r.available,e.pendingIssue?'확인 필요':e.withPending?'현재 배정 확인':'실제 출고만'];let sheets;
 if(detail){if(detailIndex===null||!results[detailIndex])throw Error('상품 상세를 먼저 선택해 주세요.');const e=entry(results[detailIndex],detailIndex,dailyDetailDay);sheets=[{name:'판매처상세',headers:['일자/기간','판매처','구분','합계 (개)','실제 출고 (개)','배정 대기 (개)'],rows:Object.entries(e.channels).sort((a,b)=>b[1]-a[1]).map(([n,q])=>[e.day||periodDates().join(' ~ '),n,n==='판매처 미확인'?'확인 필요':rocketChannel(n)?'로켓배송':'로켓배송 외',e.pendingIssue?'확인 필요':q,e.day?e.r.shippedDaily[e.day]?.[n]||0:e.r.shippedChannels[n]||0,e.withPending?(e.pendingIssue?'확인 필요':e.r.pendingChannels[n]||0):'당시 자료 없음']),widths:[28,28,20,20,20,25],emphasis:[3]},{name:'품목정보',headers,rows:[toRow(e,'-')],widths:[28,9,40,24,24,22,22,25,24,28,25,25,24],emphasis:[5]}];}else sheets=[{name:'일자별순위',headers,rows:daysInPeriod().flatMap(day=>sortEntries(results.map((r,i)=>entry(r,i,day))).map((e,i)=>toRow(e,i+1))),widths:[24,9,40,24,24,22,22,25,24,28,25,25,24],emphasis:[5]},{name:'기간합산순위',headers,rows:ranked.map((e,i)=>toRow(e,i+1)),widths:[28,9,40,24,24,22,22,25,24,28,25,25,24],emphasis:[5]}];
 sheets.push({name:'조회기준',headers:['항목','내용'],rows:[['선택 기간',periodDates().join(' ~ ')],['조회 시점',new Date(ranDataAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})],['검색어',ranKeyword||'전체 상품'],['배정 기준','오늘 행에만 현재 확인된 배정 대기. 과거 행에는 배정을 넣지 않음.'],['전일 대비','실제 출고만 비교. 기간 합산 순위에서는 종료일 실제 출고 vs 전일.'],['전체 내보내기','상위 품목 표시 제한과 관계없이 모든 출고 품목'],['주의','확인 필요 표시는 확정 수량 0이 아님'],['MD 참고',dailyRule]],widths:[28,95]});const safe=s=>String(s).replace(/[<>:"/\\|?*\u0000-\u001F]/g,'_').slice(0,80);return {bytes:createXlsx(sheets,ranDataAt),filename:'요미몬_일자별출고_'+(detail?safe(results[detailIndex].name)+'_'+(dailyDetailDay||'기간합산')+'_':'')+periodDates().join('_')+'.xlsx'};
 }
